import React, { useState, useEffect, useMemo, useRef, useTransition, useCallback } from 'react';
import { useSearchParams } from 'react-router-dom';
import { motion } from 'framer-motion';
import { getRooms, getRecommendations, getProfile } from '../api/listingService';
import { Input } from '../components/ui/input';
import { Slider } from '../components/ui/slider';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../components/ui/select';
import { Button } from '../components/ui/button';
import { Sheet, SheetContent, SheetTrigger, SheetTitle } from '../components/ui/sheet';
import { FaFilter, FaRupeeSign, FaSearch, FaBars, FaCrosshairs, FaStar, FaChevronLeft, FaChevronRight } from 'react-icons/fa';
import RoomCard from '../components/listings/RoomCard';
import Pagination from '../components/ui/Pagination';
import { getUserLocation, applyRoadDistances } from '../utils/distance';
import { useGoogleMaps } from '../context/GoogleMapsContext';
import { Autocomplete } from '@react-google-maps/api';
import { useAuth } from '../context/AuthContext';
import useDebounce from '../hooks/useDebounce';
import { toast } from "sonner";

// Filter Controls Component (Mobile & Desktop)
const FilterControls = ({ filters, setFilters, nearMeActive, nearMeLoading, onNearMe, onClearNearMe, onPlaceSelected, onClearSearch, isMapLoaded, autocompleteRef, selectedPlace, setSelectedPlace, showMobileFilters, setShowMobileFilters, onFilterChange, isPending, setFiltersOptimized }) => {
    const handleFilterChange = (key, value) => {
        if (setFiltersOptimized) {
            setFiltersOptimized(key, value);
        } else {
            setFilters(prev => ({ ...prev, [key]: value }));
        }
        if (onFilterChange) onFilterChange();
    };

    return (
        <div className="mb-6">
            {/* Desktop Filters - Single Line Layout */}
            <div className={`hidden md:flex items-center gap-3 p-4 bg-white rounded-xl border border-gray-200 shadow-sm ${isPending ? 'opacity-70' : ''}`}>
                {/* Search Bar — bigger and wider */}
                <div className="flex-1 flex items-center gap-2 bg-gray-50 rounded-lg px-4 py-3 border border-gray-200 min-w-[400px]">
                    <FaSearch className="text-gray-400 flex-shrink-0 text-xl" />
                    <div className="flex-1">
                        {isMapLoaded ? (
                            <Autocomplete
                                onLoad={(ref) => (autocompleteRef.current = ref)}
                                onPlaceChanged={onPlaceSelected}
                            >
                                <input
                                    type="text"
                                    placeholder="Search by college, area, or room title..."
                                    value={selectedPlace || filters.searchQuery}
                                    onChange={(e) => {
                                        if (selectedPlace) setSelectedPlace('');
                                        handleFilterChange('searchQuery', e.target.value);
                                    }}
                                    className="w-full outline-none bg-transparent text-base placeholder-gray-400"
                                    style={{ minWidth: '100%' }}
                                />
                            </Autocomplete>
                        ) : (
                            <input
                                type="text"
                                placeholder="Search by location or room title..."
                                value={filters.searchQuery}
                                onChange={(e) => handleFilterChange('searchQuery', e.target.value)}
                                className="w-full outline-none bg-transparent text-base placeholder-gray-400"
                            />
                        )}
                    </div>
                    {(selectedPlace || filters.searchQuery) && (
                        <button
                            onClick={onClearSearch}
                            className="text-gray-400 hover:text-gray-600 flex-shrink-0"
                        >
                            ✕
                        </button>
                    )}
                </div>

                {/* Near Me Button */}
                <Button
                    variant={nearMeActive ? "default" : "outline"}
                    size="sm"
                    onClick={nearMeActive ? onClearNearMe : onNearMe}
                    disabled={nearMeLoading}
                    className={`whitespace-nowrap h-10 px-4 ${nearMeActive ? 'bg-green-700 hover:bg-green-800' : 'text-green-700 border-green-700 hover:bg-green-50'}`}
                >
                    {nearMeLoading ? (
                        <span className="mr-1 inline-block h-4 w-4 border-2 border-current border-t-transparent rounded-full animate-spin" />
                    ) : (
                        <FaCrosshairs className="mr-1" />
                    )}
                    {nearMeLoading ? 'Locating...' : nearMeActive ? 'Clear' : 'Near Me'}
                </Button>

                {/* Distance Slider (visible when Near Me is active) */}
                {nearMeActive && (
                    <div className="flex items-center gap-2 bg-gray-50 px-3 py-1 rounded-lg">
                        <span className="text-sm text-gray-500 whitespace-nowrap">
                            <strong>{filters.maxDistance}</strong> km
                        </span>
                        <input
                            type="range"
                            min="1"
                            max="20"
                            step="1"
                            value={filters.maxDistance}
                            onChange={(e) => handleFilterChange('maxDistance', Number(e.target.value))}
                            className="w-20 accent-green-700"
                        />
                    </div>
                )}

                {/* Max Price Slider */}
                <div className="flex items-center gap-2 bg-gray-50 px-3 py-2 rounded-lg">
                    <FaRupeeSign className="text-gray-400 flex-shrink-0" />
                    <div className="w-[160px]">
                        <div className="flex items-center gap-1 mb-1">
                            <span className="text-xs text-gray-500">Up to</span>
                            <Input
                                type="number"
                                placeholder="50000"
                                value={filters.maxPrice}
                                onChange={(e) => handleFilterChange('maxPrice', e.target.value)}
                                className="h-7 w-[100px] text-xs px-2 py-0 text-center border-gray-200"
                            />
                        </div>
                        <Slider
                            min={0}
                            max={50000}
                            step={500}
                            value={[Number(filters.maxPrice) || 50000]}
                            onValueChange={([val]) => handleFilterChange('maxPrice', val === 0 ? '' : String(val))}
                            className="w-full"
                        />
                    </div>
                </div>

                {/* Room Type */}
                <Select value={filters.roomType} onValueChange={(value) => handleFilterChange('roomType', value)}>
                    <SelectTrigger className="w-[130px] h-10">
                        <SelectValue placeholder="All Types" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">All Types</SelectItem>
                        <SelectItem value="single">Single</SelectItem>
                        <SelectItem value="double">Double</SelectItem>
                        <SelectItem value="triple">Triple</SelectItem>
                    </SelectContent>
                </Select>

                {/* Gender */}
                <Select value={filters.gender} onValueChange={(value) => handleFilterChange('gender', value)}>
                    <SelectTrigger className="w-[130px] h-10">
                        <SelectValue placeholder="All Genders" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="any">Any Gender</SelectItem>
                        <SelectItem value="boys">Boys Only</SelectItem>
                        <SelectItem value="girls">Girls Only</SelectItem>
                    </SelectContent>
                </Select>
            </div>

            {/* Mobile Filters */}
            <div className="md:hidden">
                <div className="flex items-center justify-between mb-4">
                    {/* Near Me button (mobile) */}
                    <Button
                        variant={nearMeActive ? "default" : "outline"}
                        size="sm"
                        onClick={nearMeActive ? onClearNearMe : onNearMe}
                        disabled={nearMeLoading}
                        className={nearMeActive ? 'bg-green-700 hover:bg-green-800' : 'text-green-700 border-green-700'}
                    >
                        {nearMeLoading ? (
                            <span className="mr-1 inline-block h-4 w-4 border-2 border-current border-t-transparent rounded-full animate-spin" />
                        ) : (
                            <FaCrosshairs className="mr-1" />
                        )}
                        {nearMeLoading ? 'Locating...' : nearMeActive ? 'Clear' : 'Near Me'}
                    </Button>

                    <Sheet open={showMobileFilters} onOpenChange={setShowMobileFilters}>
                        <SheetTrigger asChild>
                            <Button variant="outline" className="ml-2">
                                <FaFilter className="mr-2" /> Filters
                            </Button>
                        </SheetTrigger>
                        <SheetContent side="bottom" className="h-[80vh] overflow-y-auto">
                            <SheetTitle className="mb-4">Filter Rooms</SheetTitle>

                            <div className="space-y-4">
                                <div>
                                    <label className="block text-sm font-medium mb-1">Search College/Area/Title</label>
                                    {isMapLoaded ? (
                                        <Autocomplete
                                            onLoad={(ref) => (autocompleteRef.current = ref)}
                                            onPlaceChanged={onPlaceSelected}
                                        >
                                            <Input
                                                placeholder="Search by college, area, or title..."
                                                value={selectedPlace || filters.searchQuery}
                                                onChange={(e) => {
                                                    if (selectedPlace) setSelectedPlace('');
                                                    handleFilterChange('searchQuery', e.target.value);
                                                }}
                                            />
                                        </Autocomplete>
                                    ) : (
                                        <Input
                                            placeholder="Search by location or title..."
                                            value={filters.searchQuery}
                                            onChange={(e) => handleFilterChange('searchQuery', e.target.value)}
                                        />
                                    )}
                                </div>

                                {/* Distance Slider (mobile) */}
                                {nearMeActive && (
                                    <div>
                                        <label className="block text-sm font-medium mb-1">
                                            Distance: Within {filters.maxDistance} km
                                        </label>
                                        <input
                                            type="range"
                                            min="1"
                                            max="20"
                                            step="1"
                                            value={filters.maxDistance}
                                            onChange={(e) => handleFilterChange('maxDistance', Number(e.target.value))}
                                            className="w-full accent-green-700"
                                        />
                                    </div>
                                )}

                                <div>
                                    <label className="block text-sm font-medium mb-1">Max Rent</label>
                                    <div className="flex items-center gap-1 mb-2">
                                        <span className="text-sm text-gray-500">Up to</span>
                                        <Input
                                            type="number"
                                            placeholder="50000"
                                            value={filters.maxPrice}
                                            onChange={(e) => handleFilterChange('maxPrice', e.target.value)}
                                            className="h-8 text-sm py-0"
                                        />
                                    </div>
                                    <Slider
                                        min={0}
                                        max={50000}
                                        step={500}
                                        value={[Number(filters.maxPrice) || 50000]}
                                        onValueChange={([val]) => handleFilterChange('maxPrice', String(val))}
                                        className="w-full"
                                    />
                                </div>

                                <div>
                                    <label className="block text-sm font-medium mb-1">Room Type</label>
                                    <Select value={filters.roomType} onValueChange={(value) => handleFilterChange('roomType', value)}>
                                        <SelectTrigger>
                                            <SelectValue placeholder="Select Room Type" />
                                        </SelectTrigger>
                                        <SelectContent>
                                            <SelectItem value="all">All Types</SelectItem>
                                            <SelectItem value="single">Single</SelectItem>
                                            <SelectItem value="double">Double</SelectItem>
                                            <SelectItem value="triple">Triple</SelectItem>
                                        </SelectContent>
                                    </Select>
                                </div>

                                <div>
                                    <label className="block text-sm font-medium mb-1">Gender</label>
                                    <Select value={filters.gender} onValueChange={(value) => handleFilterChange('gender', value)}>
                                        <SelectTrigger>
                                            <SelectValue placeholder="Select Gender" />
                                        </SelectTrigger>
                                        <SelectContent>
                                            <SelectItem value="any">Any Gender</SelectItem>
                                            <SelectItem value="boys">Boys Only</SelectItem>
                                            <SelectItem value="girls">Girls Only</SelectItem>
                                        </SelectContent>
                                    </Select>
                                </div>
                            </div>
                        </SheetContent>
                    </Sheet>

                    <Button variant="outline" size="sm" className="ml-2" onClick={() => setShowMobileFilters(true)}>
                        <FaBars className="text-green-700" />
                    </Button>
                </div>
            </div>
        </div>
    );
};

const RoomsPage = ({ headerContent }) => {
    const [searchParams] = useSearchParams();
    const { user } = useAuth();
    const [rooms, setRooms] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [nearMeActive, setNearMeActive] = useState(false);
    const [nearMeLoading, setNearMeLoading] = useState(false);
    const [showMobileFilters, setShowMobileFilters] = useState(false);
    const [selectedPlace, setSelectedPlace] = useState('');
    const autocompleteRef = useRef(null);
    const recommendedScrollRef = useRef(null);
    const [recommendedRooms, setRecommendedRooms] = useState([]);
    const [loadingRecommendations, setLoadingRecommendations] = useState(false);
    const [isPending, startTransition] = useTransition();

    const { isLoaded: isMapLoaded, isMapsAvailable } = useGoogleMaps();

    const [filters, setFilters] = useState(() => {
        const urlSearch = searchParams.get('searchQuery') || '';
        const urlRoomType = searchParams.get('roomType') || 'all';
        const urlGender = searchParams.get('gender') || 'any';
        return {
            searchQuery: urlSearch,
            maxPrice: '',
            gender: urlGender,
            roomType: urlRoomType,
            userLat: null,
            userLng: null,
            maxDistance: 5,
        };
    });

    const [currentPage, setCurrentPage] = useState(1);
    const itemsPerPage = 12;

    // Near Me handler — get browser location
    const handleNearMe = async () => {
        setNearMeLoading(true);
        try {
            const loc = await getUserLocation();
            setFilters(prev => ({ ...prev, userLat: loc.lat, userLng: loc.lng }));
            setNearMeActive(true);
        } catch (err) {
            toast.error(err.message || 'Could not get your location. Please try again.');
        } finally {
            setNearMeLoading(false);
        }
    };

    const handleClearNearMe = () => {
        setSelectedPlace('');
        setFilters(prev => ({ ...prev, userLat: null, userLng: null, maxDistance: 5 }));
        setNearMeActive(false);
    };

    // Google Places Autocomplete — location-based search by place name
    const handlePlaceSelected = () => {
        const place = autocompleteRef.current?.getPlace();
        if (place && place.geometry) {
            const placeName = place.formatted_address || place.name || '';
            setSelectedPlace(placeName);
            setFilters(prev => ({
                ...prev,
                searchQuery: '',
                userLat: place.geometry.location.lat(),
                userLng: place.geometry.location.lng(),
            }));
            setNearMeActive(true);
        }
    };

    // Clear search input (both text and place-based)
    const handleClearSearch = () => {
        setSelectedPlace('');
        if (nearMeActive) {
            setFilters(prev => ({ ...prev, searchQuery: '', userLat: null, userLng: null, maxDistance: 5 }));
            setNearMeActive(false);
        } else {
            setFilters(prev => ({ ...prev, searchQuery: '' }));
        }
    };

    // Paginate rooms
    const paginatedRooms = useMemo(() => {
        const startIndex = (currentPage - 1) * itemsPerPage;
        return rooms.slice(startIndex, startIndex + itemsPerPage);
    }, [rooms, currentPage]);

    const handlePageChange = (page) => {
        setCurrentPage(page);
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    const handleFilterChange = () => {
        setCurrentPage(1);
    };

    const setFiltersOptimized = (key, value) => {
        startTransition(() => {
            setFilters(prev => ({ ...prev, [key]: value }));
        });
    };

    // Debounced searchQuery
    const debouncedSearchQuery = useDebounce(filters.searchQuery, 500);
    const debouncedMaxDistance = useDebounce(filters.maxDistance, 300);

    // Memoized filters for fetch dependency
    const memoizedFilters = useMemo(() => {
        return {
            search: (nearMeActive && selectedPlace) ? '' : debouncedSearchQuery,
            maxPrice: filters.maxPrice,
            gender: filters.gender,
            roomType: filters.roomType,
            sortBy: filters.sortBy,
            lat: filters.userLat,
            lng: filters.userLng,
            maxDistance: filters.userLat ? debouncedMaxDistance : null,
        };
    }, [
        debouncedSearchQuery,
        filters.maxPrice,
        filters.gender,
        filters.roomType,
        filters.sortBy,
        filters.userLat,
        filters.userLng,
        debouncedMaxDistance,
        nearMeActive,
        selectedPlace
    ]);

    // Fetch rooms — passes filters to backend API
    useEffect(() => {
        const fetchRooms = async () => {
            setLoading(true);
            try {
                const results = await getRooms(memoizedFilters);
                let roomsList = results || [];
                if (roomsList.length > 0 && nearMeActive && filters.userLat && filters.userLng && isMapsAvailable) {
                    roomsList = await applyRoadDistances(roomsList, filters.userLat, filters.userLng);
                }
                setRooms(roomsList);
            } catch (err) {
                setError('Failed to fetch rooms. Please try again later.');
                console.error("Error fetching rooms:", err);
            } finally {
                setLoading(false);
            }
        };

        fetchRooms();
    }, [memoizedFilters, nearMeActive, filters.userLat, filters.userLng, isMapsAvailable]);

    useEffect(() => {
        const fetchRecommendations = async () => {
            if (!user || user.role !== 'student' || !user.profileComplete) {
                return;
            }
            setLoadingRecommendations(true);
            try {
                const recommendationsData = await getRecommendations('room', 8);
                let recs = recommendationsData?.recommendations || [];

                if (recs.length > 0 && isMapsAvailable) {
                    const profileData = await getProfile().catch(() => null);
                    if (profileData) {
                        const collegeLat = profileData?.personal?.collegeLat;
                        const collegeLng = profileData?.personal?.collegeLng;
                        if (collegeLat && collegeLng) {
                            recs = await applyRoadDistances(recs, collegeLat, collegeLng);
                        }
                    }
                }

                setRecommendedRooms(recs);
            } catch (err) {
                console.error("Error fetching recommendations:", err);
                setRecommendedRooms([]);
            } finally {
                setLoadingRecommendations(false);
            }
        };

        fetchRecommendations();
    }, [user, isMapLoaded, isMapsAvailable]);

    // Scroll handlers for recommendations
    const scrollRecommendations = useCallback((direction) => {
        const container = recommendedScrollRef.current;
        if (container) {
            const scrollAmount = 340;
            container.scrollTo({
                left: container.scrollLeft + (direction === 'left' ? -scrollAmount : scrollAmount),
                behavior: 'smooth'
            });
        }
    }, [recommendedScrollRef]);

    return (
        <div className="min-h-screen bg-gray-50">
            {headerContent}

            {/* Green Header Banner */}
            <div className="bg-green-900 py-12 px-4 text-white">
                <div className="container mx-auto px-4">
                    <h1 className="text-5xl font-bold text-center mb-8">
                        Find Your Perfect <span className="text-yellow-200">Student Home</span>
                    </h1>
                    <p className="text-center text-gray-200 max-w-2xl mx-auto">
                        Discover comfortable, affordable rooms tailored for students. Filter by budget, amenities, and location to find your ideal match.
                    </p>
                </div>
            </div>

            <div className="container mx-auto px-4 py-8">
                <FilterControls filters={filters} setFilters={setFilters} nearMeActive={nearMeActive} nearMeLoading={nearMeLoading} onNearMe={handleNearMe} onClearNearMe={handleClearNearMe} onPlaceSelected={handlePlaceSelected} onClearSearch={handleClearSearch} isMapLoaded={isMapLoaded} autocompleteRef={autocompleteRef} selectedPlace={selectedPlace} setSelectedPlace={setSelectedPlace} showMobileFilters={showMobileFilters} setShowMobileFilters={setShowMobileFilters} onFilterChange={handleFilterChange} isPending={isPending} setFiltersOptimized={setFiltersOptimized} />

                {/* Recommended For You Section */}
                {loadingRecommendations && (
                    <div className="mb-8">
                        <h2 className="text-xl font-bold text-gray-800 mb-4 flex items-center gap-2">
                            <FaStar className="text-yellow-500" /> Recommended For You
                        </h2>
                        <div className="flex items-center gap-4">
                            <div ref={recommendedScrollRef} className="flex flex-nowrap gap-4 overflow-x-auto pb-4 snap-x flex-1">
                                {Array.from({ length: 4 }).map((_, i) => (
                                    <div key={i} className="w-[280px] sm:w-[320px] bg-white rounded-xl shadow-md p-4 animate-pulse snap-start flex-shrink-0">
                                        <div className="h-48 bg-gray-200 rounded-lg mb-4"></div>
                                        <div className="h-4 bg-gray-200 rounded w-3/4 mb-2"></div>
                                        <div className="h-3 bg-gray-200 rounded w-1/2 mb-4"></div>
                                        <div className="h-10 bg-gray-200 rounded-lg"></div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                )}
                {recommendedRooms.length > 0 && !loadingRecommendations && (
                    <div className="mb-8">
                        <div className="flex items-center justify-between mb-4">
                            <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                                <FaStar className="text-yellow-500" /> Recommended For You
                            </h2>
                            <div className="flex gap-2">
                                <button
                                    onClick={() => scrollRecommendations('left')}
                                    className="p-2 rounded-full bg-white border border-gray-300 hover:bg-gray-100 transition-colors shadow-sm"
                                    aria-label="Scroll left"
                                >
                                    <FaChevronLeft className="text-gray-600" />
                                </button>
                                <button
                                    onClick={() => scrollRecommendations('right')}
                                    className="p-2 rounded-full bg-white border border-gray-300 hover:bg-gray-100 transition-colors shadow-sm"
                                    aria-label="Scroll right"
                                >
                                    <FaChevronRight className="text-gray-600" />
                                </button>
                            </div>
                        </div>
                        <div ref={recommendedScrollRef} className="flex flex-nowrap gap-4 overflow-x-auto pb-4 snap-x" style={{ scrollBehavior: 'smooth' }}>
                            {recommendedRooms.map(room => (
                                <div key={room.room_id} className="w-[280px] sm:w-[320px] snap-start flex-shrink-0">
                                    <RoomCard
                                        room={room}
                                        showAvailability={true}
                                        recommendationScore={room.recommendationScore}
                                        matchReasons={room.matchReasons}
                                    />
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {/* Separator */}
                <hr className="my-6 border-gray-300" />

                {/* Results count */}
                {rooms.length > 0 && !loading && (
                    <div className="mb-4">
                        <p className="text-gray-600">
                            Showing <span className="font-semibold">{rooms.length}</span> properties
                            {nearMeActive && (
                                <span className="text-green-700 ml-1">within {filters.maxDistance} km</span>
                            )}
                        </p>
                    </div>
                )}

                {loading ? (
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                        {Array.from({ length: 6 }).map((_, index) => (
                            <div key={index} className="bg-white rounded-xl shadow-md p-4 animate-pulse">
                                <div className="h-48 bg-gray-200 rounded-lg mb-4"></div>
                                <div className="h-4 bg-gray-200 rounded w-3/4 mb-2"></div>
                                <div className="h-3 bg-gray-200 rounded w-1/2 mb-4"></div>
                                <div className="h-10 bg-gray-200 rounded-lg"></div>
                            </div>
                        ))}
                    </div>
                ) : error ? (
                    <div className="text-center py-12">
                        <p className="text-red-500 text-lg">{error}</p>
                        <Button onClick={() => window.location.reload()} className="mt-4">
                            Retry
                        </Button>
                    </div>
                ) : rooms.length > 0 ? (
                    <>
                        <motion.div
                            initial="hidden"
                            animate="visible"
                            variants={{
                                hidden: { opacity: 0 },
                                visible: {
                                    opacity: 1,
                                    transition: {
                                        staggerChildren: 0.05
                                    }
                                }
                            }}
                            className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6"
                        >
                            {paginatedRooms.map(room => (
                                <motion.div
                                    key={room.room_id}
                                    variants={{
                                        hidden: { opacity: 0, y: 20 },
                                        visible: { opacity: 1, y: 0 }
                                    }}
                                >
                                    <RoomCard room={room} showAvailability={true} />
                                </motion.div>
                            ))}
                        </motion.div>
                        <Pagination
                            currentPage={currentPage}
                            totalItems={rooms.length}
                            itemsPerPage={itemsPerPage}
                            onPageChange={handlePageChange}
                        />
                    </>
                ) : (
                    <div className="text-center py-12">
                        <FaSearch className="mx-auto text-gray-400 text-4xl mb-4" />
                        <h3 className="text-xl font-semibold text-gray-800 mb-2">No rooms found</h3>
                        <p className="text-gray-600 mb-4">
                            Try adjusting your filters to find what you're looking for.
                        </p>
                        <Button onClick={() => {
                            setFilters({
                                searchQuery: '',
                                maxPrice: '',
                                gender: 'any',
                                roomType: 'all',
                                availableOnly: false,
                                userLat: null,
                                userLng: null,
                                maxDistance: 5,
                            });
                            setNearMeActive(false);
                            setSelectedPlace('');
                        }}>
                            Reset Filters
                        </Button>
                    </div>
                )}
            </div>
        </div>
    );
};

export default RoomsPage;