import React from 'react';
import PropTypes from 'prop-types';
import { Link } from 'react-router-dom';
import { FaMapMarkerAlt, FaBed } from 'react-icons/fa';
import { Card, CardContent } from "../ui/card";
import { Badge } from "../ui/badge";
import { Button } from "../ui/button";
import RecommendationBadge from './RecommendationBadge';
import ReviewBadge from './ReviewBadge';
import { displayDistance } from '../../utils/distance';

const RoomCard = ({ room, showAvailability = false, recommendationScore = null, matchReasons = null }) => {
    if (!room) return null;

    const {
        room_id,
        cover_photo_url,
        title,
        description,
        rent,
        roomType,
        facilities = [],
        address,
        rating,
        reviewCount,
        availability
    } = room;

    const isAvailable = availability !== false && availability !== 'false';

    // Dynamic feature from facilities array
    const mainFacilities = facilities.slice(0, 3);
    const remainingCount = facilities.length - mainFacilities.length;

    return (
        <Card className="relative overflow-hidden shadow-md hover:shadow-lg transition-shadow duration-300 group border border-gray-200 bg-white h-[460px] flex flex-col py-0">
            {/* Image container — no overflow-hidden so RecommendationBadge tooltip can float freely */}
            <div className="relative h-52">
                <Link to={`/rooms/${room_id}`} className="block h-full">
                    {cover_photo_url ? (
                        <img
                            src={cover_photo_url}
                            alt={title || 'Room Image'}
                            className="w-full h-52 object-cover"
                            loading='lazy'
                        />
                    ) : (
                        <div className="w-full h-52 bg-gray-200 flex items-center justify-center">
                            <span className="text-gray-500">No Image Available</span>
                        </div>
                    )}
                </Link>

                {/* Price badge (top right) */}
                <Badge
                    variant="secondary"
                    className="absolute top-3 right-3 bg-green-700 text-white font-bold border-none text-sm py-1 px-3"
                >
                    ₹{Number(rent).toLocaleString('en-IN')} /mo
                </Badge>

                {/* Availability Badge (top left) */}
                {showAvailability && (
                    <Badge
                        className={`absolute top-3 left-3 font-semibold text-xs py-0.5 px-2 ${
                            isAvailable
                                ? 'bg-green-100 text-green-800 border border-green-300'
                                : 'bg-red-600/90 text-white border-none'
                        }`}
                    >
                        {isAvailable ? 'Available' : 'Unavailable'}
                    </Badge>
                )}
            </div>

            {/* Recommendation Badge — outside image div, positioned relative to Card
                so its tooltip can float over card content without being clipped */}
            <RecommendationBadge score={recommendationScore} reasons={matchReasons} className="top-11 right-3" />

            <CardContent className="p-4 py-2 space-y-2 flex-grow flex flex-col">
                {/* Title + Rating */}
                <div className="flex justify-between items-start gap-2">
                    <h3 className="text-lg font-bold text-gray-800 truncate group-hover:text-primary transition-colors flex-1">
                        <Link to={`/rooms/${room_id}`}>{title}</Link>
                    </h3>
                    <ReviewBadge rating={rating} count={reviewCount} className="flex-shrink-0" />
                </div>

                {/* Description */}
                {description && (
                    <p className="text-sm text-gray-600 line-clamp-2 min-h-[2.5rem]">{description}</p>
                )}

                {/* Location */}
                <div className="flex items-start gap-1 text-gray-600 text-sm min-h-[2.5rem]">
                    <FaMapMarkerAlt className="w-4 h-4 text-green-700 flex-shrink-0 mt-0.5" />
                    <span className="break-words line-clamp-2 flex-1">
                        {address || "Near Campus"}
                    </span>
                    {room.distance !== undefined && room.distance !== null && (() => {
                        const dist = displayDistance(room.distance, room.distanceIsExact);
                        return dist !== null ? (
                            <Badge variant="outline" className="ml-1 py-0.5 px-1.5 text-xs whitespace-nowrap flex-shrink-0 text-green-700 border-green-300 mt-0.5">
                                ~{dist} km
                            </Badge>
                        ) : null;
                    })()}
                </div>

                {/* Room Type + Facilities */}
                <div className="flex flex-wrap items-center gap-1 min-h-[3rem] content-start">
                    {roomType && (
                        <Badge variant="outline" className="py-0.5 px-1.5 text-xs flex items-center gap-1">
                            <FaBed className="w-3 h-3 text-green-700" />
                            <span className="capitalize">{roomType}</span>
                        </Badge>
                    )}
                    {mainFacilities.map((facility, index) => (
                        <Badge key={index} variant="outline" className="py-0.5 px-1.5 font-normal text-xs">
                            {facility}
                        </Badge>
                    ))}
                    {remainingCount > 0 && (
                        <Badge variant="outline" className="py-0.5 px-1.5 font-normal text-xs">
                            +{remainingCount}
                        </Badge>
                    )}
                </div>

                {/* View Details Button */}
                <Link to={`/rooms/${room_id}`} className="block w-full mt-auto pt-2 pb-2">
                    <Button
                        variant="default"
                        className={`w-full font-semibold rounded-lg py-2 flex items-center justify-center gap-2 ${isAvailable ? 'bg-green-700 hover:bg-green-800 text-white' : 'bg-gray-400 hover:bg-gray-500 text-white'}`}
                        disabled={showAvailability && !isAvailable}
                    >
                        {isAvailable ? (
                            <>
                                View Details
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" />
                                </svg>
                            </>
                        ) : (
                            'Unavailable'
                        )}
                    </Button>
                </Link>
            </CardContent>
        </Card>
    );
};

RoomCard.propTypes = {
    room: PropTypes.object,
    showAvailability: PropTypes.bool,
    recommendationScore: PropTypes.number,
    matchReasons: PropTypes.array,
};

export default React.memo(RoomCard);